"""Standard physics AI benchmark suite.

:class:`PhysicsBenchmark` evaluates any model that implements
``forward(state_t, descriptor) → state_tp1`` against a curated set of
physics tasks with known reference solutions.

Benchmark tasks
---------------
Each task is defined by a :class:`BenchmarkTask` with:
* Reference trajectories generated by a classical solver.
* Standard metrics: RMSE, relative-L2, rollout divergence step.
* Physics-specific checks: energy conservation, mass conservation,
  divergence-free velocity fields.

Supported tasks (``BUILTIN_TASKS``)::

    "heat_2d_smooth"      — linear diffusion, smooth IC
    "burgers_1d_shock"    — nonlinear Burgers, shock formation
    "wave_1d_standing"    — standing wave, energy conservation
    "advection_2d_gaussian" — Gaussian blob advection
    "ns2d_lid_driven"     — lid-driven cavity Navier-Stokes
    "heat_multiscale"     — multiscale diffusion, fine features

Quick start::

    from pinneapple_worldmodel.benchmark import PhysicsBenchmark

    bench = PhysicsBenchmark(device="cuda")
    results = bench.run(model, tasks=["heat_2d_smooth", "burgers_1d_shock"])
    bench.print_report(results)
"""
from __future__ import annotations

import logging
import math
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Sequence, Tuple

import torch
import torch.nn as nn
from torch import Tensor
from torch.utils.data import DataLoader

from .scenario import BUILTIN_SCENARIOS, PhysicsScenario
from .simulator import PhysicsSimulator

log = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# BenchmarkTask
# ---------------------------------------------------------------------------

@dataclass
class BenchmarkTask:
    """A single benchmark evaluation task.

    Parameters
    ----------
    name : str — unique identifier.
    scenario_name : str — maps to BUILTIN_SCENARIOS.
    n_trajectories : int — reference trajectories.
    rollout_steps : int — maximum autoregressive unrolling.
    seed : int — deterministic reference data seed.
    physics_checks : list of str — which conservation laws to verify.
    metrics : list of str — which metrics to compute.
    description : str
    """
    name: str
    scenario_name: str
    n_trajectories: int = 20
    rollout_steps: int = 10
    seed: int = 42
    physics_checks: List[str] = field(default_factory=list)
    metrics: List[str] = field(
        default_factory=lambda: ["rmse", "rel_l2", "rollout_rmse", "div_step"]
    )
    description: str = ""


# ---------------------------------------------------------------------------
# Built-in tasks
# ---------------------------------------------------------------------------

