# ---------------------------------------------------------------------------
# BenchmarkResult
# ---------------------------------------------------------------------------

@dataclass
class BenchmarkResult:
    """Results for one BenchmarkTask.

    Parameters
    ----------
    task_name : str
    next_step_rmse : float
    rollout_rmse : float — RMSE averaged across all rollout steps.
    rel_l2 : float
    div_step : int — first rollout step where RMSE exceeds 10×step-1 RMSE
                     (divergence indicator; -1 = never diverged).
    physics_scores : dict — per-check score in [0, 1] (1 = conserved).
    n_trajectories : int
    model_name : str
    """
    task_name: str
    next_step_rmse: float
    rollout_rmse: float
    rel_l2: float
    div_step: int
    physics_scores: Dict[str, float]
    n_trajectories: int
    model_name: str = "unknown"

    def overall_score(self) -> float:
        """Scalar in [0, 1] — higher is better.

        Combines relative-L2 (inverted) and physics scores.
        """
        phys = sum(self.physics_scores.values()) / max(len(self.physics_scores), 1)
        acc = max(0.0, 1.0 - self.rel_l2)
        return 0.6 * acc + 0.4 * phys


# ---------------------------------------------------------------------------
# PhysicsBenchmark
# ---------------------------------------------------------------------------

class PhysicsBenchmark:
    """Evaluate physics AI models on standard tasks.

    Parameters
    ----------
    device : str
    verbose : bool

    Example
    -------
    >>> bench = PhysicsBenchmark(device="cuda")
    >>> results = bench.run(model, tasks=["heat_2d_smooth", "burgers_1d_shock"])
    >>> bench.print_report(results)
    """

    def __init__(self, device: str = "cpu", verbose: bool = True) -> None:
        self.device = device
        self.verbose = verbose

    # ------------------------------------------------------------------
    # Main
    # ------------------------------------------------------------------

    def run(
        self,
        model: nn.Module,
        *,
        tasks: Optional[List[str]] = None,
        custom_tasks: Optional[List[BenchmarkTask]] = None,
        model_name: str = "model",
        context_fn: Optional[Callable[[str], Any]] = None,
    ) -> Dict[str, BenchmarkResult]:
        """Run benchmark tasks and return results.

        Parameters
        ----------
        model : any nn.Module with forward(state_t, descriptor) → state_tp1.
        tasks : list of task names (from BUILTIN_TASKS) or None for all.
        custom_tasks : additional BenchmarkTask objects to run.
        model_name : str — label in the report.
        context_fn : callable(scenario_name) → descriptor.  Used to produce
            the physics descriptor passed to the model.  Default: zeros.

        Returns
        -------
        dict of task_name → BenchmarkResult.
        """
        task_list: List[BenchmarkTask] = []
        if tasks is None:
            task_list = list(BUILTIN_TASKS.values())
        else:
            for t in tasks:
                if t not in BUILTIN_TASKS:
                    raise ValueError(f"Unknown task: {t!r}. Available: {list(BUILTIN_TASKS)}")
                task_list.append(BUILTIN_TASKS[t])
        if custom_tasks:
            task_list.extend(custom_tasks)

        if self.verbose:
            print(f"\n[PhysicsBenchmark] Running {len(task_list)} task(s) "
                  f"on model '{model_name}'")

        results: Dict[str, BenchmarkResult] = {}
        model.eval()
        model_dev = next((p.device for p in model.parameters()), torch.device(self.device))

        for task in task_list:
            if self.verbose:
                print(f"  ▶ {task.name} …", end=" ", flush=True)
            try:
                result = self._run_task(task, model, model_dev, context_fn, model_name)
                results[task.name] = result
                if self.verbose:
                    print(f"rmse={result.next_step_rmse:.4g}  "
                          f"rel_l2={result.rel_l2:.4g}  "
                          f"score={result.overall_score():.3f}")
            except Exception as exc:
                log.warning("Task '%s' failed: %s", task.name, exc)
                if self.verbose:
                    print(f"FAILED ({exc})")

        return results

    # ------------------------------------------------------------------
    # Single task evaluation
    # ------------------------------------------------------------------

    @torch.no_grad()
    def _run_task(
        self,
        task: BenchmarkTask,
        model: nn.Module,
        device: torch.device,
        context_fn: Optional[Callable],
        model_name: str,
    ) -> BenchmarkResult:
        sc = BUILTIN_SCENARIOS[task.scenario_name]
        sim = PhysicsSimulator(sc, device=self.device, verbose=False)

        trajs = []
        for seed in range(task.n_trajectories):
            try:
                t = sim.generate_trajectory(seed=task.seed + seed)
                trajs.append(t)
            except Exception:
                continue

        if not trajs:
            raise RuntimeError(f"No trajectories generated for task '{task.name}'.")

        # Build samples manually from trajectories
        samples = []
        mean_stat = torch.zeros(sc.n_fields, *sc.grid_shape)
        std_stat = torch.ones(sc.n_fields, *sc.grid_shape)

        for traj in trajs:
            states = traj.states  # (T+1, C, *grid)
            T = states.shape[0] - 1
            for t in range(T):
                samples.append({
                    "state_t": states[t],
                    "state_tp1": states[t + 1],
                    "context": torch.zeros(sc.n_params + 1),
                    "params": torch.zeros(sc.n_params),
                    "scenario": sc.name,
                })

        if not samples:
            raise RuntimeError("No samples extracted from trajectories.")

        # --- Next-step metrics ---
        rmse_vals, rel_l2_vals = [], []
        for s in samples[:200]:  # cap for speed
            st = s["state_t"].unsqueeze(0).to(device)
            tp1 = s["state_tp1"].unsqueeze(0).to(device)
            ctx = self._make_context(task.scenario_name, context_fn, device)
            pred = model(st, ctx)
            rmse_vals.append(torch.sqrt(torch.mean((pred - tp1) ** 2)).item())
            rel_l2_vals.append(
                (torch.norm(pred - tp1) / (torch.norm(tp1) + 1e-8)).item()
            )

        next_step_rmse = sum(rmse_vals) / len(rmse_vals)
        rel_l2 = sum(rel_l2_vals) / len(rel_l2_vals)

        # --- Rollout metrics ---
        rollout_rmse_vals = []
        div_step = -1
        step1_rmse = next_step_rmse

        for traj in trajs[:5]:
            states = traj.states
            T = states.shape[0] - 1
            if T < task.rollout_steps:
                continue

            state = states[0].unsqueeze(0).to(device)
            for step in range(1, min(task.rollout_steps, T) + 1):
                ctx = self._make_context(task.scenario_name, context_fn, device)
                state = model(state, ctx)
                ref = states[step].unsqueeze(0).to(device)
                rmse = torch.sqrt(torch.mean((state - ref) ** 2)).item()
                rollout_rmse_vals.append(rmse)

                if div_step == -1 and step > 1 and rmse > 10 * step1_rmse:
                    div_step = step

        rollout_rmse = (
            sum(rollout_rmse_vals) / len(rollout_rmse_vals) if rollout_rmse_vals else 0.0
        )

        # --- Physics checks ---
        physics_scores = {}
        for check in task.physics_checks:
            physics_scores[check] = self._check_physics(
                check, model, trajs[:3], task.scenario_name, context_fn, device
            )

        return BenchmarkResult(
            task_name=task.name,
            next_step_rmse=next_step_rmse,
            rollout_rmse=rollout_rmse,
            rel_l2=rel_l2,
            div_step=div_step,
            physics_scores=physics_scores,
            n_trajectories=len(trajs),
            model_name=model_name,
        )

    # ------------------------------------------------------------------
    # Physics checks
    # ------------------------------------------------------------------

    @torch.no_grad()
    def _check_physics(
        self,
        check: str,
        model: nn.Module,
        trajs: List[Any],
        scenario_name: str,
        context_fn: Optional[Callable],
        device: torch.device,
    ) -> float:
        """Return a conservation score in [0, 1] (1 = perfectly conserved)."""
        scores = []
        for traj in trajs:
            states = traj.states
            T = states.shape[0] - 1
            if T < 2:
                continue
            ctx = self._make_context(scenario_name, context_fn, device)
            state = states[0].unsqueeze(0).to(device)

            energies_pred, energies_ref = [], []
            for t in range(1, min(T + 1, 5)):
                state = model(state, ctx)
                e_pred = torch.mean(state ** 2).item()
                e_ref = torch.mean(states[t].to(device) ** 2).item()
                energies_pred.append(e_pred)
                energies_ref.append(e_ref)

            if check == "energy_decay":
                # Score: fraction of steps where predicted energy is non-increasing
                if len(energies_pred) > 1:
                    ok = sum(
                        1 for i in range(1, len(energies_pred))
                        if energies_pred[i] <= energies_pred[i - 1] + 1e-6
                    )
                    scores.append(ok / (len(energies_pred) - 1))
                else:
                    scores.append(1.0)

            elif check == "energy_conservation":
                # Score: relative std of energy over trajectory
                if energies_pred:
                    e = torch.tensor(energies_pred)
                    rel_std = (e.std() / (e.mean().abs() + 1e-8)).item()
                    scores.append(max(0.0, 1.0 - rel_std))

            elif check == "mass_conservation":
                # Score: relative change in total mass (integral of field)
                ref0 = states[0].to(device).sum().item()
                diffs = []
                s = states[0].unsqueeze(0).to(device)
                for t in range(1, min(T + 1, 5)):
                    s = model(s, ctx)
                    mass = s.sum().item()
                    diffs.append(abs(mass - ref0) / (abs(ref0) + 1e-8))
                if diffs:
                    scores.append(max(0.0, 1.0 - sum(diffs) / len(diffs)))

            elif check == "divergence_free":
                # Score: mean |div u| relative to |u| (for velocity fields)
                s = states[0].unsqueeze(0).to(device)
                s = model(s, ctx)
                if s.shape[1] >= 2:  # at least 2 velocity components
                    ux = s[:, 0]
                    uy = s[:, 1]
                    # Finite-difference divergence
                    dudx = torch.diff(ux, dim=-1).abs().mean().item()
                    dvdy = torch.diff(uy, dim=-2).abs().mean().item()
                    mag = s[:, :2].norm(dim=1).mean().item() + 1e-8
                    div_norm = (dudx + dvdy) / mag
                    scores.append(max(0.0, 1.0 - div_norm))
                else:
                    scores.append(1.0)

            else:
                scores.append(1.0)

        return sum(scores) / max(len(scores), 1)

    # ------------------------------------------------------------------
    # Helpers
    # ------------------------------------------------------------------

    def _make_context(
        self,
        scenario_name: str,
        context_fn: Optional[Callable],
        device: torch.device,
    ) -> Optional[Any]:
        if context_fn is not None:
            ctx = context_fn(scenario_name)
            if isinstance(ctx, Tensor):
                return ctx.to(device)
            return ctx
        return None

    # ------------------------------------------------------------------
    # Report
    # ------------------------------------------------------------------

    def print_report(self, results: Dict[str, BenchmarkResult]) -> None:
        """Print a formatted leaderboard-style report."""
        print("\n" + "=" * 72)
        print(f"{'PHYSICS AI BENCHMARK REPORT':^72}")
        print("=" * 72)
        print(f"{'Task':<26} {'RMSE':>8} {'Rel-L2':>8} {'Roll-RMSE':>10} "
              f"{'DivStep':>8} {'Score':>7}")
        print("-" * 72)
        for name, r in sorted(results.items()):
            ds = str(r.div_step) if r.div_step > 0 else "—"
            print(f"{name:<26} {r.next_step_rmse:>8.4g} {r.rel_l2:>8.4g} "
                  f"{r.rollout_rmse:>10.4g} {ds:>8} {r.overall_score():>7.3f}")
        print("=" * 72)
        all_scores = [r.overall_score() for r in results.values()]
        if all_scores:
            print(f"  Overall mean score: {sum(all_scores) / len(all_scores):.3f}")
            model_name = next(iter(results.values())).model_name
            print(f"  Model: {model_name}")
        print("=" * 72 + "\n")

    # ------------------------------------------------------------------
    # Compare multiple models
    # ------------------------------------------------------------------

    def compare(
        self,
        models: Dict[str, nn.Module],
        *,
        tasks: Optional[List[str]] = None,
        context_fns: Optional[Dict[str, Callable]] = None,
    ) -> Dict[str, Dict[str, BenchmarkResult]]:
        """Run the benchmark for multiple models and return a comparison dict.

        Parameters
        ----------
        models : dict mapping model_name → nn.Module.
        tasks : list of task names or None for all.
        context_fns : optional dict of model_name → context_fn.

        Returns
        -------
        dict of model_name → {task_name → BenchmarkResult}.
        """
        all_results: Dict[str, Dict[str, BenchmarkResult]] = {}
        for name, model in models.items():
            ctx_fn = (context_fns or {}).get(name)
            all_results[name] = self.run(
                model, tasks=tasks, model_name=name, context_fn=ctx_fn
            )

        # Summary table
        if self.verbose:
            print("\n" + "=" * 56)
            print(f"{'MODEL COMPARISON':^56}")
            print("=" * 56)
            print(f"{'Model':<30} {'Mean Score':>10} {'Best Task':>15}")
            print("-" * 56)
            for mname, res in all_results.items():
                if res:
                    scores = {t: r.overall_score() for t, r in res.items()}
                    mean = sum(scores.values()) / len(scores)
                    best = max(scores, key=scores.get)  # type: ignore
                    print(f"{mname:<30} {mean:>10.3f} {best:>15}")
            print("=" * 56 + "\n")

        return all_results
